INSERT INTO data_point (
    uuid, line_id, point_no, x_coord, y_coord, z_coord, collect_time,
    collector_id, device_id, status, create_by, create_time, update_by, update_time, note, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{lineId}, #{pointNo}, #{xCoord}, #{yCoord}, #{zCoord}, #{collectTime},
             #{collectorId}, #{deviceId}, #{status}, #{createBy}, #{createTime}, #{updateBy}, #{updateTime}, #{note}, #{isDel}
         )
